# -*- coding: utf-8 -*-
"""
网易云音乐 Web 播放服务(独立版)
从 LX-Pro-Music-Python 抽取网易云音源,提供搜索 + 播放的本地 Web 服务,端口 5000

启动:
    python3 server.py            # 监听 0.0.0.0:5000
    WY_COOKIE='MUSIC_U=xxx' python3 server.py   # 可选:带网易云登录 Cookie 解锁 VIP 歌曲
"""
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import requests
from flask import Flask, Response, jsonify, request, send_from_directory
from urllib.parse import quote as _url_quote

# 是否启用第三方取链兑底(官方取不到链接时,如 VIP/无版权歌曲)
TOUBIEC_ENABLED = os.environ.get('TOUBIEC_ENABLED', '1') != '0'

app = Flask(__name__)   # 单文件版:无静态目录


@app.after_request
def _no_cache(resp):
    """禁用页面缓存,保证刷新即拿到最新版本(旧缓存页会导致热歌点击误触发搜索等历史行为)"""
    resp.headers['Cache-Control'] = 'no-cache, no-store, must-revalidate'
    resp.headers['Pragma'] = 'no-cache'
    resp.headers['Expires'] = '0'
    return resp

# 搜索缓存:songmid -> song dict(供 /api/url 按 id 取歌)
_song_cache = {}
_SONG_CACHE_MAX = 2000

# 播放链接缓存:songmid|quality -> (url, via, ts),TTL 10 分钟(第三方接口有限流)
_url_cache = {}
_URL_CACHE_TTL = 600
_URL_CACHE_MAX = 500
import time as _time

QUALITY_LABELS = {'hires': 'Hi-Res', 'flac': 'FLAC', '320k': '320k', '128k': '128k'}


def _cache_songs(song_list):
    for s in song_list:
        if len(_song_cache) >= _SONG_CACHE_MAX:
            _song_cache.clear()
        _song_cache[s['songmid']] = s


@app.get('/')
def index():
    return _emb_html()   # 内嵌界面(密文解密)


@app.get('/api/xhttp')
def api_xhttp():
    """D键·自定义音源专用HTTP代理(v3.71):洛雪源脚本在WebView内无CORS豁免,
    统一经http_fetch中转;base64回传防二进制损坏;单次≤8MB,retry=1快速失败。"""
    import base64 as _b64
    url = (request.args.get('url') or '').strip()
    if not url.startswith(('http://', 'https://')):
        return jsonify({'code': 400, 'message': '非法URL'})
    method = (request.args.get('method') or 'get').lower()
    if method not in ('get', 'post', 'head'):      # v3.85:放行head供校验弹窗真·可下性探测
        method = 'get'
    try:
        hdrs = json.loads(_b64.b64decode(request.args.get('headers', '')).decode('utf-8')) if request.args.get('headers') else {}
    except Exception:
        hdrs = {}
    try:
        body = _b64.b64decode(request.args.get('body', '')) if request.args.get('body') else None
    except Exception:
        body = None
    try:
        timeout = min(float(request.args.get('timeout', '12') or 12), 20.0)
    except Exception:
        timeout = 12.0
    try:
        resp = http_fetch(url, method=method, headers=hdrs if hdrs else None, data=body,
                          timeout=timeout, retry=1)
    except Exception as e:
        return jsonify({'code': 502, 'message': str(e)[:180]})
    b = resp.get('body')
    if isinstance(b, (bytes, bytearray)):
        if len(b) > 8 * 1024 * 1024:
            return jsonify({'code': 413, 'message': '响应过大'})
        out, is_bin = _b64.b64encode(bytes(b)).decode('ascii'), True
    elif isinstance(b, (dict, list)):
        out, is_bin = json.dumps(b, ensure_ascii=False), False
    else:
        out, is_bin = (b if isinstance(b, str) else str(b)), False
    ct = ''
    try:
        h = resp.get('headers') or {}
        ct = h.get('Content-Type') or h.get('content-type') or ''
    except Exception:
        pass
    return jsonify({'code': 200, 'status': resp.get('status_code', 0), 'ctype': ct, 'b64': is_bin, 'body': out})

@app.get('/api/search')
def api_search():
    keyword = (request.args.get('keyword') or '').strip()
    if not keyword:
        return jsonify({'code': 400, 'message': '缺少 keyword 参数'})
    page = max(int(request.args.get('page', 1) or 1), 1)
    limit = min(int(request.args.get('limit', 20) or 20), 50)
    try:
        res = wy.search(keyword, page, limit)
    except Exception as e:
        return jsonify({'code': 500, 'message': str(e)})
    _cache_songs(res['list'])
    return jsonify({
        'code': 200,
        'data': {
            'list': res['list'],
            'total': res.get('total', 0),
            'page': page,
            'limit': limit,
            'allPage': res.get('allPage', 0),
        },
    })


@app.get('/api/url')
def api_url():
    songmid = (request.args.get('songmid') or '').strip()
    quality = (request.args.get('quality') or '320k').strip()
    if not songmid:
        return jsonify({'code': 400, 'message': '缺少 songmid 参数'})
    if quality not in QUALITY_LABELS:
        quality = '320k'
    song, err = _get_song_obj(songmid)
    if err:
        return jsonify({'code': 400, 'message': err})
    url, via, err = _resolve_music_url(song, songmid, quality)
    if err:
        return jsonify({'code': 500, 'message': err})
    return jsonify({'code': 200, 'data': {'url': url, 'quality': quality, 'via': via}})


def _get_song_obj(songmid):
    """从缓存取歌曲对象;无缓存则用最小对象兑底。返回 (song, error)。"""
    song = _song_cache.get(songmid)
    if song is not None:
        return song, None
    try:
        song_id = int(songmid)
    except ValueError:
        return None, 'songmid 无效'
    return {
        'source': 'wy', 'songmid': songmid, 'name': '', 'singer': '',
        'img': '', 'interval': '', 'albumName': '', 'albumId': '',
        'types': [], 'typeUrl': {},
        'meta': {'songId': song_id},
    }, None


def _resolve_music_url(song, songmid, quality):
    """官方优先取直链,失败走第三方兑底(带限流缓存)。返回 (url, via, error)。"""
    try:
        return wy.get_music_url(song, quality), 'netease', None
    except Exception as e1:
        if not TOUBIEC_ENABLED:
            return None, '', str(e1)
        # 第三方取链(带缓存,避免触发限流)
        cache_key = f'{songmid}|{quality}'
        hit = _url_cache.get(cache_key)
        if hit and hit[2] + _URL_CACHE_TTL > _time.time():
            return hit[0], hit[1], None
        try:
            url = toubiec.get_song_url(songmid, quality)
            if len(_url_cache) >= _URL_CACHE_MAX:
                _url_cache.clear()
            _url_cache[cache_key] = (url, 'toubiec', _time.time())
            return url, 'toubiec', None
        except Exception as e2:
            return None, '', f'官方失败: {e1}; 第三方失败: {e2}'


def _cd_header(filename, ctype) :
    """构建下载响应头:双文件名(ASCII 回退 + RFC 5987 中文)兼容所有浏览器,
    部分安卓浏览器/WebView 不认 filename*,会回退按 MIME 命名导致后缀错误。"""
    base, dot, ext = filename.rpartition('.')
    ascii_base = re.sub(r'[^A-Za-z0-9._ -]', '', base).strip(' -_.') or 'download'
    ascii_name = f"{ascii_base}.{ext}" if dot else ascii_base
    return {
        'Content-Disposition': f"attachment; filename=\"{ascii_name}\"; filename*=UTF-8''{_url_quote(filename)}",
        'Content-Type': ctype,
        'Cache-Control': 'no-store',
    }


def _sniff_audio(head, fallback):
    """根据文件头嗅探真实音频格式,返回 (扩展名, MIME)。(v3.92自api_download提取供合并下载共用)"""
    if head[:4] == b'fLaC':
        return 'flac', 'audio/flac'
    if len(head) >= 8 and head[4:8] == b'ftyp':
        return 'm4a', 'audio/mp4'          # MP4/M4A 容器(部分歌曲 AAC 源)
    if head[:2] in (b'\xff\xf1', b'\xff\xf9'):
        return 'aac', 'audio/aac'          # ADTS AAC 裸流
    if head[:3] == b'ID3':
        return 'mp3', 'audio/mpeg'
    if len(head) > 1 and head[0] == 0xFF and (head[1] & 0xE0) == 0xE0 and (head[1] & 0x06):
        return 'mp3', 'audio/mpeg'         # MPEG 帧同步(层位非 00)
    return fallback, ('audio/mpeg' if fallback == 'mp3' else 'audio/flac')


def _embed_metadata(path, ext, meta):
    """v3.92合并下载:mutagen按容器嵌入标题/歌手/专辑/歌词/封面。返回是否实际嵌入。
    mp3→ID3v2.3(USLT歌词+APIC封面);m4a/mp4→ilst(©lyr/covr);flac→VORBIS+PICTURE;其余容器原样保留。"""
    title, artist, album = meta['title'], meta['artist'], meta['album']
    lrc, pic = (meta.get('lyric') or '').strip(), meta.get('pic') or b''
    if not any((title, artist, album, lrc, pic)):
        return False
    if ext == 'mp3':
        from mutagen.id3 import ID3, ID3NoHeaderError, USLT, APIC, TIT2, TPE1, TALB
        try:
            tags = ID3(path)
        except ID3NoHeaderError:
            tags = ID3()
        tags.delall('USLT')
        tags.add(TIT2(encoding=3, text=[title]))
        if artist:
            tags.add(TPE1(encoding=3, text=[artist]))
        if album:
            tags.add(TALB(encoding=3, text=[album]))
        if lrc:
            tags.add(USLT(encoding=3, lang='chi', desc='', text=lrc))
        if pic:
            mime = 'image/png' if pic[:4] == b'\x89PNG' else 'image/jpeg'
            tags.delall('APIC')
            tags.add(APIC(encoding=3, mime=mime, type=3, desc='', data=pic))
        tags.update_to_v23()
        tags.save(path, v2_version=3)
        return True
    if ext in ('m4a', 'mp4'):
        from mutagen.mp4 import MP4, MP4Cover
        audio = MP4(path)
        audio['\xa9nam'] = [title]
        if artist:
            audio['\xa9ART'] = [artist]
        if album:
            audio['\xa9alb'] = [album]
        if lrc:
            audio['\xa9lyr'] = [lrc]
        if pic:
            fmt = MP4Cover.FORMAT_PNG if pic[:4] == b'\x89PNG' else MP4Cover.FORMAT_JPEG
            audio['covr'] = [MP4Cover(pic, imageformat=fmt)]
        audio.save()
        return True
    if ext == 'flac':
        from mutagen.flac import FLAC, Picture
        audio = FLAC(path)
        audio['TITLE'] = title
        if artist:
            audio['ARTIST'] = artist
        if album:
            audio['ALBUM'] = album
        if lrc:
            audio['LYRICS'] = lrc
        if pic:
            p = Picture()
            p.type, p.desc = 3, ''
            p.mime = 'image/png' if pic[:4] == b'\x89PNG' else 'image/jpeg'
            p.data = pic
            audio.clear_pictures()
            audio.add_picture(p)
        audio.save()
        return True
    return False                      # aac/wav/ape等:原样保留不嵌入


@app.get('/api/merge')
def api_merge():
    """合并下载(v3.92):下载当前歌曲→官方歌词+官方图床封面嵌入元数据→落盘暂存目录,
    由JS桥promote转存公共Download后清理。流程对应用户诉求:先下完歌,再快速嵌入并提示成功。"""
    import time as _tm
    songmid = (request.args.get('songmid') or '').strip()
    quality = (request.args.get('quality') or '320k').strip()
    if quality not in QUALITY_LABELS:
        quality = '320k'
    stage = (request.args.get('stage') or '').strip()
    if not stage.startswith('/') or '..' in stage:
        return jsonify({'code': 400, 'message': '缺少暂存目录'}), 400
    song, err = _get_song_obj(songmid)
    if err:
        return jsonify({'code': 400, 'message': err}), 400
    # ① 歌词:v3.94优先取前端已加载的歌词数据(播放器经stageText写入的暂存文件,与显示完全一致),官方接口兑底
    lrc_text = ''
    lrcfile = (request.args.get('lrcfile') or '').strip()
    if lrcfile and '/' not in lrcfile and '\\' not in lrcfile and '..' not in lrcfile:
        lp = os.path.join(stage, lrcfile)
        try:
            if os.path.isfile(lp):
                with open(lp, encoding='utf-8', errors='replace') as fh:
                    lrc_text = (fh.read() or '').strip()
                os.remove(lp)
        except Exception:
            pass
    if not lrc_text:
        try:
            ldata, _, _ = _fetch_lyric(song, songmid)
            if ldata:
                lrc_text = ((ldata.get('lyric') or '') + '\n' + (ldata.get('tlyric') or '')).strip()
        except Exception:
            pass
    # ② 封面:前端当前封面URL直传(与播放器显示同源),兑底缓存对象img;jpg/png魔数校验
    pic_src = (request.args.get('picurl') or '').strip() or (song.get('img') or '')
    pic_bytes = b''
    if pic_src.startswith(('http://', 'https://')):
        try:
            pr = requests.get(pic_src, timeout=(10, 20), headers={'User-Agent': 'Mozilla/5.0'})
            if pr.status_code == 200 and pr.content[:3] in (b'\xff\xd8\xff',) or pr.content[:4] == b'\x89PNG':
                pic_bytes = pr.content
        except Exception:
            pass
    # ③ 音频直链(音源接管时前端传url覆盖,与下载歌曲按钮同源)
    direct = (request.args.get('url') or '').strip()
    if direct.startswith(('http://', 'https://')):
        url, uerr = direct, None
    else:
        url, _, uerr = _resolve_music_url(song, songmid, quality)
    if uerr or not url:
        return jsonify({'code': 502, 'message': f'取链失败: {uerr}'}), 502
    try:
        up = requests.get(url, stream=True, timeout=(10, 60), headers={'User-Agent': 'Mozilla/5.0'})
    except Exception as e:
        return jsonify({'code': 502, 'message': f'拉取音频失败: {e}'}), 502
    if up.status_code != 200:
        up.close()
        return jsonify({'code': 502, 'message': f'直链响应异常({up.status_code})'}), 502
    it = up.iter_content(chunk_size=64 * 1024)
    first = next(it, b'')
    req_ext = 'flac' if quality == 'flac' else 'mp3'
    ext, _ct = _sniff_audio(first, req_ext)
    safe = lambda s2: re.sub(r'[\\/:*?"<>|]', '_', (s2 or '').strip()) or '未知'
    base = f"{safe(song.get('name'))}-{safe(song.get('singer'))}"
    try:
        os.makedirs(stage, exist_ok=True)
    except Exception as e:
        return jsonify({'code': 500, 'message': f'暂存目录不可用: {e}'}), 500
    tmp_path = os.path.join(stage, f'.mrg_{int(_tm.time())}_{_tm.time_ns() % 100000}.{ext}')
    try:
        with open(tmp_path, 'wb') as fo:
            if first:
                fo.write(first)
            for chunk in it:
                if chunk:
                    fo.write(chunk)
    except Exception as e:
        up.close()
        try:
            os.remove(tmp_path)
        except Exception:
            pass
        return jsonify({'code': 500, 'message': f'写入暂存失败: {e}'}), 500
    up.close()
    # ④ 元数据嵌入(mutagen自动适配容器;失败不影响音频本身)
    embedded = False
    embed_err = ''
    try:
        embedded = _embed_metadata(tmp_path, ext, {
            'title': song.get('name') or '', 'artist': song.get('singer') or '',
            'album': song.get('albumName') or '', 'lyric': lrc_text, 'pic': pic_bytes,
        })
    except Exception as e:
        embed_err = str(e)[:120]
    fname = f'{base}.{ext}'
    final_path = os.path.join(stage, fname)
    k = 1
    while os.path.exists(final_path):
        final_path = os.path.join(stage, f'{base}({k}).{ext}')
        k += 1
    os.rename(tmp_path, final_path)
    tip = '已嵌入歌词与封面' if embedded else (
        ('未支持该容器嵌入，已保留原音频' + (f'（{embed_err}）' if embed_err else ''))
        if ext not in ('mp3', 'm4a', 'flac') else '无可用歌词/封面，仅保存音频')
    return jsonify({'code': 200, 'data': {'filename': os.path.basename(final_path),
                                          'embedded': embedded, 'ext': ext, 'tip': tip}})


@app.get('/api/download')
def api_download():
    """流式代理下载:同源请求 + Content-Disposition 强制浏览器以 歌名-歌手.mp3/flac 保存,
    避免直链跨域导致文件被命名为 .mpga 等错误后缀。"""
    songmid = (request.args.get('songmid') or '').strip()
    quality = (request.args.get('quality') or '320k').strip()
    if not songmid:
        return jsonify({'code': 400, 'message': '缺少 songmid 参数'}), 400
    if quality not in QUALITY_LABELS:
        quality = '320k'
    song, err = _get_song_obj(songmid)
    if err:
        return jsonify({'code': 400, 'message': err}), 400
    # 文件名基础:歌名-歌手(过滤非法字符,扩展名待嗅探后确定)
    safe = lambda s: re.sub(r'[\\/:*?"<>|]', '_', (s or '').strip()) or '未知'
    base = f"{safe(song.get('name'))}-{safe(song.get('singer'))}"
    req_ext = 'flac' if quality == 'flac' else 'mp3'
    url, _, err = _resolve_music_url(song, songmid, quality)
    if err:
        return jsonify({'code': 500, 'message': err}), 502
    try:
        upstream = requests.get(url, stream=True, timeout=(10, 60),
                                headers={'User-Agent': 'Mozilla/5.0'})
    except Exception as e:
        return jsonify({'code': 502, 'message': f'拉取音频失败: {e}'}), 502
    if upstream.status_code != 200:
        upstream.close()
        return jsonify({'code': 502, 'message': f'直链响应异常({upstream.status_code})'}), 502

    # 预读首个数据块用于嗅探真实容器格式
    it = upstream.iter_content(chunk_size=64 * 1024)
    first = next(it, b'')
    ext, ctype = _sniff_audio(first, req_ext)
    filename = f"{base}.{ext}"

    # info=1:仅探测真实格式即返回,不传输音频体(前端用于让提示后缀与实际文件一致)
    if request.args.get('info'):
        upstream.close()
        return jsonify({'code': 200, 'data': {'ext': ext, 'ctype': ctype, 'filename': filename}})

    def gen():
        try:
            if first:
                yield first
            for chunk in it:
                if chunk:
                    yield chunk
        finally:
            upstream.close()

    headers = _cd_header(filename, ctype)
    if 'Content-Length' in upstream.headers:
        headers['Content-Length'] = upstream.headers['Content-Length']
    return Response(gen(), headers=headers)


@app.get('/api/lyric')
def api_lyric():
    songmid = (request.args.get('songmid') or '').strip()
    if not songmid:
        return jsonify({'code': 400, 'message': '缺少 songmid 参数'})
    song = _song_cache.get(songmid)
    if song is None:
        try:
            song_id = int(songmid)
        except ValueError:
            return jsonify({'code': 400, 'message': 'songmid 无效'})
        song = {'songmid': songmid, 'meta': {'songId': song_id}}
    data, via, lerr = _fetch_lyric(song, songmid)
    if data is None:
        if not TOUBIEC_ENABLED:
            return jsonify({'code': 500, 'message': lerr or '官方接口失败'}), 500
        return jsonify({'code': 500, 'message': f'官方失败: {lerr}; 第三方无有效歌词'}), 500
    return jsonify({'code': 200, 'data': data, 'via': via})


def _fetch_lyric(song, songmid):
    """歌词获取策略:官方优先,第三方仅兜底。返回 (data, via, error)。"""
    official_err = None
    try:
        data = wy.lyric(song)
    except Exception as e1:
        official_err = str(e1)
        data = None
    if data and (data.get('lyric') or '').strip():
        return data, 'netease', None
    if TOUBIEC_ENABLED:
        try:
            td = toubiec.get_lyric(songmid)
            tlrc = ((td or {}).get('lyric') or '').strip()
            if tlrc and not tlrc.startswith('{'):
                return td, 'toubiec', None
        except Exception:
            pass
    if data is not None:
        return data, 'netease', None
    return None, '', official_err or '官方接口失败'


@app.get('/api/download-lyric')
def api_download_lyric():
    """歌词文件下载:同源请求 + Content-Disposition 强制浏览器以 歌名-歌手.lrc 保存,
    避免前端 Blob 下载被浏览器按 MIME 改成 .txt 等错误后缀。"""
    songmid = (request.args.get('songmid') or '').strip()
    if not songmid:
        return jsonify({'code': 400, 'message': '缺少 songmid 参数'}), 400
    song, err = _get_song_obj(songmid)
    if err:
        return jsonify({'code': 400, 'message': err}), 400
    data, _, lerr = _fetch_lyric(song, songmid)
    lrc = ((data or {}).get('lyric') or '').strip()
    if not lrc:
        return jsonify({'code': 404, 'message': lerr or '暂无歌词'}), 404
    content = lrc
    tlyric = ((data or {}).get('tlyric') or '').strip()
    if tlyric:
        content += '\n\n' + tlyric
    safe = lambda s: re.sub(r'[\\/:*?"<>|]', '_', (s or '').strip()) or '未知'
    filename = f"{safe(song.get('name'))}-{safe(song.get('singer'))}.lrc"
    # octet-stream 强制下载:防止浏览器按 text/plain 渲染并改名为 .txt
    return Response(content, headers=_cd_header(filename, 'application/octet-stream'))


def _resolve_mvid(song, songmid):
    """从官方歌曲对象提取 MV id(搜索数据 meta.mv 字段)。0/缺失 → None。"""
    mv = (song.get('meta') or {}).get('mv')
    try:
        mvid = int(mv)
    except (TypeError, ValueError):
        return None
    return mvid if mvid > 0 else None


