def get_html():
    """供 Java 层调用:把界面 HTML 渲染进 WebView(无端口架构,无需等服务启动)。"""
    return _emb_html()


def _ensure_init():
    """桥接模式一次性初始化(幂等)。"""
    global _BRIDGE_INITED
    if _BRIDGE_INITED:
        return
    cookie = os.environ.get('WY_COOKIE', '')
    if cookie:
        set_wy_cookie(cookie)
    else:
        saved = _load_cookie_file()      # 启动自检:cooir.json 有内容则代入全局变量供取链调用
        if saved:
            set_wy_cookie(saved)
    _BRIDGE_INITED = True


_BRIDGE_INITED = False


def handle_api(path):
    """JS 桥接入口(无端口模式核心):WebView 页面经 AndroidBridge 直达此处,
    用 Flask test client 在进程内分发到既有路由 —— 零网络开销、零端口监听、
    路由逻辑零改动。每次调用独立 client,天然线程安全,可并发。
    返回 JSON 字符串 {"status": <http状态码>, "body": "<路由原始响应>"}"""
    _ensure_init()
    r = app.test_client(use_cookies=False).open(path, method='GET')
    body = r.get_data(as_text=True)
    # 404 兜底:未匹配路由返回的是 HTML 错误页,包装成 JSON 供前端统一处理
    if r.status_code == 404 and not body.lstrip().startswith('{'):
        body = json.dumps({'code': 404, 'message': '接口不存在'})
    return json.dumps({'status': r.status_code, 'body': body})

# ════════ 内嵌界面 index.html ════════
_EMB_KEY = bytes.fromhex(
    '9f3ac1e2' '5d84bb07' '21ce6a49' 'f0183d76'
    'ab52de90' '47c31f68' 'd9b024af' '6e1c8533'
)                                     # v3.86:与MainActivity/build.gradle/crypt_html.py同构
def _emb_stream_xor(data):
    out = bytearray(len(data)); i = counter = 0
    while i < len(data):
        h = hashlib.sha256(_EMB_KEY + counter.to_bytes(4, 'big')).digest()
        n = min(32, len(data) - i)
        for j in range(n): out[i + j] = data[i + j] ^ h[j]
        i += n; counter += 1
    return bytes(out)
_emb_cache = None
def _emb_html():
    global _emb_cache
    if _emb_cache is None:
        import base64 as _b
        _emb_cache = _emb_stream_xor(_b.b64decode(EMBEDDED_ENC)).decode('utf-8')
    return _emb_cache
EMBEDDED_ENC = ''